def isSolvable(words: list[str], result: str) -> bool:
    all_words = words + [result]
    leading = set()
    for w in all_words:
        if len(w) > 1: leading.add(w[0])
    char_weight = {}
    for w in words:
        for i, ch in enumerate(reversed(w)):
            char_weight[ch] = char_weight.get(ch, 0) + (10 ** i)
    for i, ch in enumerate(reversed(result)):
        char_weight[ch] = char_weight.get(ch, 0) - (10 ** i)
    chars = list(char_weight.keys())
    weights = [char_weight[ch] for ch in chars]
    n = len(chars)
    used = [False] * 10
    def backtrack(idx, current_sum):
        if idx == n:
            return current_sum == 0
        ch = chars[idx]
        w = weights[idx]
        start_d = 1 if ch in leading else 0
        for d in range(start_d, 10):
            if not used[d]:
                used[d] = True
                if backtrack(idx + 1, current_sum + d * w):
                    return True
                used[d] = False
        return False
    return backtrack(0, 0)

